# الوحدات الحسابية المصغّرة أ–هـ (S2_نظام_التقييم، الجزء 2؛ D44): «إحماء الحساب» درسٌ أول (d0) قبل S2-U0 وU3 وU6 وU7 وU8.
# اختبار تخطٍّ بلوحة أرقام بلا مساعدة، ونتيجته شجرة: 🟢 85% فأكثر، 🟡 60–84%، 🔴 أقل (docs/خطة_تقييم_المرحلة_2.md).
def op(a,o,b): return {"t":"calc","a":a,"op":o,"b":b}
def fn(f,n): return {"t":"calc","fn":f,"n":n}
def seq(*xs): return {"t":"calc","seq":list(xs)}
def share(n,k,q): return {"t":"calc","share":[n,k],"what":"cookie","q":q}
def rnd(m,cm,q): return {"t":"calc","round":[m,cm],"q":q}
COMMON={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} قَلَمٌ وَوَرَقَةٌ لِلْحِسَابِ؟ أَمْ نَحْسُبُ فِي الرَّأْسِ عَلَى الشَّاشَةِ؟",
 "hook.02":"{اُكْتُبِ|اُكْتُبِي} الجَوَابَ بِلَوْحَةِ الأَرْقَامِ، ثُمَّ «تَمَّ». وَلَا بَأْسَ إِنْ لَمْ {تَعْرِفْ|تَعْرِفِي}: {اُكْتُبْ|اُكْتُبِي} مَا {تَظُنُّ|تَظُنِّينَ}.",
 "res.go":"{أَنْتَ جَاهِزٌ|أَنْتِ جَاهِزَةٌ}! الشَّجَرَةُ كَبِيرَةٌ، فَهَيَّا إِلَى الحَيِّ.",
 "res.help":"{أَنْتَ جَاهِزٌ|أَنْتِ جَاهِزَةٌ}، وَنَتَذَكَّرُ الحِسَابَ مَعًا فِي الطَّرِيقِ.",
 "res.build":"نَتَدَرَّبُ قَلِيلًا مَعَ {أَهْلِكَ|أَهْلِكِ}، ثُمَّ نُعِيدُ الإِحْمَاءَ بَعْدَ أُسْبُوعٍ. وَالحَيُّ مَفْتُوحٌ {لَكَ|لَكِ}.",
 "mat.01":"{خُذِ|خُذِي} القَلَمَ وَالوَرَقَةَ، {وَاحْسُبْ|وَاحْسُبِي} عَلَيْهَا قَبْلَ لَوْحَةِ الأَرْقَامِ. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "wrap.01":"انْتَهَى الإِحْمَاءُ، وَالشَّجَرَةُ تَكْبُرُ كُلَّمَا {تَدَرَّبْتَ|تَدَرَّبْتِ}.",
}
def lesson(u, letter, title, hook1, checks, extra_lines, talk, icon='calc', pre=None):
    lines=dict(COMMON); lines["hook.01"]=hook1; lines.update(extra_lines)
    d={"id":"m2.%s.d0"%u,"title":title,"icon":[icon],"concepts":{},
       "bag":{"items":[{"icon":"pencils","label":"bagPencil"},{"icon":"paper","label":"bagPaper"}],"ask":"bag.ask","adult":"لا أدوات: إحماءٌ قصير على الشاشة (4–6 دقائق) يقيس ما تحتاجه الوحدة من الحساب.","screenPath":"على الشاشة يكتب الطفل الجواب بلوحة أرقام، بلا مساعدة ولا «أخطأت»، ثم يرى شجرة بحسب نتيجته."},
       "labels":{"bagPencil":"قَلَمٌ","bagPaper":"وَرَقَةٌ"},"lines":lines,
       "flow":[{"s":"hook","scene":"lines","mat":{"prompt":"mat.01","show":[],"icon":True,"after":"mat.02","facts":[]},"lines":["hook.01","hook.02"]},
               *(pre or []),
               {"s":"game","scene":"calcCheck","unitCalc":letter,"checks":[{"id":"c%d"%(i+1),"item":it} for i,it in enumerate(checks)],"results":{"go":"res.go","help":"res.help","build":"res.build"}},
               {"s":"wrap"}],
       "wrap":{"art":"calcArt","lines":["wrap.01"]},
       "talk":talk}
    dump(ROOT+'/content/m2/%s/d0.json'%u, d)
